import argparse
import signal
import socket
import time

# noinspection PyCompatibility
from concurrent.futures import ThreadPoolExecutor
from select import error as select_error, select

from ta_logcollector.logger import get_net_logger
from ta_logcollector.settings import req_stop, rpl_quit, SERVER_HOST, SERVER_PORT
from ta_logcollector.utils.action_runner import ActionRunner
from ta_logcollector.utils.enums import RunnerStates
from ta_logcollector.utils.socket_handler import SocketHandler

SERVER_CONTINUE = True
FORCE_KILL_ACT_PERIOD = 5


class SelectTCPServer(object):
    """
    Server based on TCP protocol and select.

    It allow communication between several Virtual Machines with dict like messages:
    - start
    - stop
    - compress
    - get state
    - get logs location
    - quit
    """

    _SERVER_CONTINUE = True

    def __init__(self, log_host, log_port):
        # type: (str, int) -> None
        """
        Main LC server
        :param log_host: host name or ip address
        :param log_port: port number
        """
        self._logger = get_net_logger(log_host, log_port, name="server_{}".format(SERVER_HOST))
        self._signal_received_time = time.time()
        self._start_handling_signals()
        self._log_host, self._log_port = log_host, log_port
        self._executor = ThreadPoolExecutor(max_workers=20)
        self._action_runner = ActionRunner(log_host, log_port)
        self._prepare_main_socket()
        self._serve()

    def _prepare_main_socket(self):
        """Creates main server socket and sets necessary options"""
        self._server = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self._set_server_socket_opts()
        self._start_server_socket()
        self._logger.info("Server started and listening at {}".format(self._server.getsockname()))

    def _set_server_socket_opts(self):
        """Sets necessary options for main server socket. Most important, this socket must be non-blocking."""
        self._server.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        self._server.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEPORT, 1)
        self._server.settimeout(None)
        self._server.setblocking(False)

    def _start_server_socket(self):
        """Binds socket and start listening"""
        self._bind_socket()
        self._prepare_handlers_lists()
        self._server.listen(65535)

    def _bind_socket(self):
        try:
            self._server.bind((SERVER_HOST, SERVER_PORT))
        except Exception as err:
            self._logger.exception(err)
            raise

    def _prepare_handlers_lists(self):
        """2 tuples for select: inputs contains only main server socket, and empty outputs"""
        self._inputs = (self._server,)
        self._outputs = ()

    def _serve(self):
        # type: () -> bool
        """
        Start main loop and start handling communication.
        Select is checking only main server socket for incoming connections.
        :return: True when exit from main loop, False on exception
        """
        while self._SERVER_CONTINUE:
            try:
                readable, _, exceptional = select(self._inputs, self._outputs, self._inputs, 0.05)
            except select_error as err:
                self._logger.debug(err, exc_info=True)
                break
            if not readable and not exceptional:
                continue
            elif exceptional:
                self._logger.debug("Main server socket died. {}".format(repr(self._server)))
                self._close_server_socket()
                return False
            self._handle_incoming_connections(readable)
        self._logger.info("Server work done.")
        return True

    def _close_server_socket(self):
        # type: () -> None
        try:
            self._server.close()
        except socket.error:
            pass

    def _handle_incoming_connections(self, readable):
        # type: (List[socket]) -> None
        """
        Basic method for handling incoming connections.
        Each new connection is accepted and work is delegated to new thread. Main loop can continue.
        :param readable: list of sockets for new connections
        :return: None
        """
        for socket_conn in readable:
            client_socket, client_address = socket_conn.accept()
            self._executor.submit(self._handle_new_client, client_socket)

    def _handle_new_client(self, client_socket):
        """
        Handles particular client on specified socket.
        Need to read message, deserialize it and act properly. When it's done, socket is being closed.
        """
        local_socket_details = client_socket.getsockname()
        remote_socket_details = client_socket.getpeername()
        try:
            socket_handler = SocketHandler(self._log_host, self._log_port, client_socket, True, 5)
            message = socket_handler.read_all()
            action_result = self._action_runner.perform_action_based_on_message(message)
            if rpl_quit["reply"] == action_result["reply"]:
                self._SERVER_CONTINUE = False
            self._logger.debug(
                "{2} <-> {1}: action {0} done".format(
                    action_result["reply"], remote_socket_details, local_socket_details
                )
            )
            socket_handler.send_msg(action_result)
        except Exception as err:
            self._logger.debug(err, exc_info=True)
        finally:
            client_socket.close()
            self._logger.debug("{} xxx {}: Socket closed".format(local_socket_details, remote_socket_details))

    def _stop_runner_on_signal_received(self, signum, frame):
        """Basic method to stop runner and quit lc_server if some of predefined signal occurs."""
        if not time.time() - self._signal_received_time < FORCE_KILL_ACT_PERIOD:
            self._logger.warning("Press <CTRL>+<C> again or send other signal within 5s to forcefully kill lc_server")
            self._signal_received_time = time.time()
            if self._action_runner.state == RunnerStates.STARTED:
                self._action_runner.perform_action_based_on_message(req_stop)
            self._SERVER_CONTINUE = False
        else:
            self._logger.warning(
                'Forcefully killing lc_server. It may leave some garbage processes. Execute "logcollector reset" may help.'
            )
            exit(1)

    def _start_handling_signals(self):
        """Basic method to handle selected signals and stop runner if any of them occurs."""
        for signal_name in [getattr(signal, name) for name in ["SIGHUP", "SIGINT", "SIGQUIT", "SIGABRT", "SIGTERM"]]:
            try:
                signal.signal(signal_name, self._stop_runner_on_signal_received)
            except (OSError, RuntimeError, ValueError):
                pass


def srv_args():
    # type: () -> argparse.Namespace
    """
    Parses provided arguments and returns dict with them
    :return: parsed arguments
    """
    parser = argparse.ArgumentParser(description="Launches select TCP server for LogCollector requests handling")
    parser.add_argument("-l", "--log_host", required=True, type=str, help="logger host")
    parser.add_argument("-p", "--log_port", required=True, type=int, help="logger port")
    args = parser.parse_args()
    return args


if __name__ == "__main__":
    cli_opts = srv_args()
    SelectTCPServer(cli_opts.log_host, cli_opts.log_port)
